// A compact first view; existing long reports remain an explicit detail page.
var matchReportTab='핵심 기록',matchReportPage=0,matchReportSeed=null;
function renderCompactMatchReport(){
 const section=$('match-popup-stats'),dialog=$('match-popup');if(!section||!dialog)return;
 const active=matchPopupActive==='stats'&&state===season.match&&!(typeof practiceSession!=='undefined'&&practiceSession);dialog.classList.toggle('compact-match-report',active);section.classList.toggle('report-compact',active);if(!active)return;
 const d=MatchReport.read(season,typeof visibleMatchForReports==='function'?visibleMatchForReports():state);if(!d.valid)return;
 if(matchReportSeed!==state.seed){matchReportSeed=state.seed;matchReportTab='핵심 기록';matchReportPage=0;}
 const narrow=typeof matchMedia==='function'&&matchMedia('(max-width:360px)').matches,playerCount=narrow?2:3,momentCount=narrow?1:2;
 const tabs=['핵심 기록','팀 비교','선수 평점','주요 장면',...(d.full&&!d.pending?['결과 상세']:[])];if(!tabs.includes(matchReportTab)){matchReportTab='핵심 기록';matchReportPage=0;}
 section.dataset.reportTab=matchReportTab;
 let host=$('compact-match-report');if(!host){host=document.createElement('div');host.id='compact-match-report';section.prepend(host);}
 const esc=escapeText,metric=r=>'<article class="match-report-metric"><small>'+esc(r.label)+'</small><div><b>'+esc(r.own)+'</b><span>:</span><b>'+esc(r.opponent)+'</b></div></article>',portrait=p=>typeof Portraits==='undefined'?'':Portraits.html(p),selected=matchReportTab;let content='',pages=1;
 if(selected==='핵심 기록')content='<div class="match-report-metrics">'+d.facts.filter(r=>['shots','xg','possession','chances'].includes(r.key)).map(metric).join('')+'</div>'+(d.best?'<button type="button" class="match-report-star" data-match-report-player="'+esc(d.best.identity)+'">'+portrait(d.best)+'<span><small>우리 최고 평점 · 기록 기반</small><b>'+esc(d.best.name)+'</b></span><strong>'+d.best.rating.toFixed(1)+'</strong></button>':'<p class="match-report-empty">출전 기록이 쌓이면 선수 평점을 확인할 수 있습니다.</p>')+'<p class="match-report-note">'+esc(d.full?'결과를 확정하면 출전 경험·회복·재정에 반영됩니다.':d.flow)+'</p>';
 else if(selected==='팀 비교'){pages=Math.ceil(d.facts.length/4);matchReportPage=Math.min(matchReportPage,pages-1);content='<div class="match-report-metrics">'+d.facts.slice(matchReportPage*4,matchReportPage*4+4).map(metric).join('')+'</div><p class="match-report-note">기록 순서: 우리 : 상대 · 점유율은 추정값, xG는 기회 품질입니다.</p>';}
 else if(selected==='선수 평점'){pages=Math.max(1,Math.ceil(d.players.length/playerCount));matchReportPage=Math.min(matchReportPage,pages-1);content='<div class="match-report-players">'+d.players.slice(matchReportPage*playerCount,matchReportPage*playerCount+playerCount).map(p=>'<button type="button" data-match-report-player="'+esc(p.identity)+'">'+portrait(p)+'<span><b>'+esc(p.name)+'</b><small>'+esc(p.pos)+' · '+p.minutes+'분 · '+esc(p.highlights.join(' · ')||'출전')+'</small></span><strong>'+p.rating.toFixed(1)+'</strong></button>').join('')+'</div><p class="match-report-note">실제 출전·득점·도움·슈팅·카드로 계산한 표시용 평점입니다.</p>'+(d.players.length?'':'<p class="match-report-empty">아직 출전 기록이 없습니다.</p>');}
 else if(selected==='주요 장면'){pages=Math.max(1,Math.ceil(d.moments.length/momentCount));matchReportPage=Math.min(matchReportPage,pages-1);content='<div class="match-report-moments">'+d.moments.slice(matchReportPage*momentCount,matchReportPage*momentCount+momentCount).map(e=>'<article data-event-type="'+esc(e.type)+'"><b>'+esc(e.minute)+'′</b><p>'+esc(typeof matchLogText==='function'?matchLogText(e.event):e.text)+'</p></article>').join('')+'</div>'+(d.moments.length?'':'<p class="match-report-empty">킥오프 뒤의 실제 장면을 표시합니다.</p>');}
 host.innerHTML='<div class="match-report-heading"><b>'+esc(d.own)+' '+d.score.join(' : ')+' '+esc(d.opponent)+'</b><small>'+esc(d.minute)+'′ · '+esc(d.status)+'</small></div><label class="match-report-select">기록 항목<select id="match-report-select" aria-label="경기 기록 항목">'+tabs.map(t=>'<option'+(t===selected?' selected':'')+'>'+t+'</option>').join('')+'</select></label>'+(selected==='결과 상세'?'<p class="match-report-note">경기 후 몸 상태, 기여 선수와 결과 반영을 자세히 확인합니다.</p>':'<section class="match-report-content" aria-label="'+esc(selected)+'">'+content+'</section>')+(pages>1?'<div class="match-report-pager"><button type="button" data-match-report-page="-1" '+(matchReportPage===0?'disabled':'')+'>이전</button><span>'+(matchReportPage+1)+' / '+pages+'</span><button type="button" data-match-report-page="1" '+(matchReportPage===pages-1?'disabled':'')+'>다음</button></div>':'')+(d.canConfirm?'<button type="button" class="primary" id="match-report-confirm">결과 확정 · 다음 일정</button>':'');
 $('match-report-select').onchange=e=>{matchReportTab=e.target.value;matchReportPage=0;renderCompactMatchReport();$('match-report-select').focus({preventScroll:true});};
 host.onclick=e=>{const page=e.target.closest('[data-match-report-page]'),player=e.target.closest('[data-match-report-player]');if(page){matchReportPage+=Number(page.dataset.matchReportPage);renderCompactMatchReport();$('compact-match-report').querySelector('[data-match-report-page="'+page.dataset.matchReportPage+'"]')?.focus({preventScroll:true});}else if(player)openPlayerDetails(player.dataset.matchReportPlayer,player);};
 const confirm=$('match-report-confirm');if(confirm)confirm.onclick=advanceSeason;
}
const compactReportPopupRender=renderMatchPopup;renderMatchPopup=function(){compactReportPopupRender();renderCompactMatchReport();};

if(typeof matchMedia==='function')matchMedia('(max-width:360px)').addEventListener('change',()=>{if(matchPopupActive==='stats')renderCompactMatchReport();});
